#!/usr/bin/env bash
# Vendor tree-sitter grammar SOURCES (MIT, per grammar) into grammar-sources/.
# These are the BUILD INPUTS the CI grammar forge compiles into the WASM
# parsers REVA ships (js/vendor/ts/) — grammar.js (hand-written DSL) +
# src/parser.c (generated by tree-sitter generate) + scanner + node-types.
# Vendoring them makes the parser code load-bearing: npm distributes exactly
# these files; our CI compiles exactly these files.
# Usage: bash scripts/vendor-grammars.sh
set -uo pipefail
cd "$(dirname "$0")/.."
ROOT=$(pwd)
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

# name:npm-package[@version][:subdir] — pinned to 0.22-CLI-compatible
# grammar.js DSL (npm-latest grammars use newer DSL the ABI-14 CLI rejects);
# subdir for grammars that ship multiple in one package
GRAMMARS="
javascript:tree-sitter-javascript@0.21.4
typescript:tree-sitter-typescript@0.21.1:typescript
tsx:tree-sitter-typescript@0.21.1:tsx
python:tree-sitter-python
html:tree-sitter-html
css:tree-sitter-css@0.21.1
json:tree-sitter-json
bash:tree-sitter-bash
c:tree-sitter-c
cpp:tree-sitter-cpp@0.22.3
java:tree-sitter-java
kotlin:tree-sitter-kotlin
rust:tree-sitter-rust
go:tree-sitter-go
php:tree-sitter-php@0.22.6:php
ruby:tree-sitter-ruby
lua:tree-sitter-lua
sql:tree-sitter-sql
yaml:tree-sitter-yaml
"

mkdir -p "$ROOT/grammar-sources"
FAIL=""
echo "$GRAMMARS" | while read -r entry; do
  [ -z "$entry" ] && continue
  name="${entry%%:*}"
  rest="${entry#*:}"
  pkg="${rest%%:*}"
  sub="${rest#*:}"
  sub="${sub#*:}"          # no subdir case: rest==pkg → sub==pkg → strip again
  [ "$sub" = "$pkg" ] && sub=""
  echo "== $name ($pkg${sub:+ / $sub}) =="
  # resolve the tarball URL from the npm packument (pinned version or latest)
  PKGNAME="${pkg%%@*}"
  URL=$(curl -sL "https://registry.npmjs.org/$PKGNAME" | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>{try{const j=JSON.parse(d);const want=process.argv[1]||'';const v=want&&j.versions[want]?want:j['dist-tags'].latest;console.log(j.versions[v].dist.tarball)}catch(e){console.log('')}})" "${pkg##*@}")
  if [ -z "$URL" ]; then echo "  SKIP: no npm packument for $pkg"; FAIL="$FAIL $name"; continue; fi
  curl -sL -o "$TMP/$name.tgz" "$URL" || { echo "  SKIP: download failed"; FAIL="$FAIL $name"; continue; }
  rm -rf "$TMP/x"; mkdir -p "$TMP/x"; tar -xzf "$TMP/$name.tgz" -C "$TMP/x" || { echo "  SKIP: bad tarball"; continue; }
  SRC="$TMP/x/package"
  [ -n "$sub" ] && SRC="$SRC/$sub"
  if [ ! -f "$SRC/src/parser.c" ]; then echo "  SKIP: no src/parser.c in $pkg ($SRC)"; FAIL="$FAIL $name"; continue; fi
  DEST="$ROOT/grammar-sources/$name"
  rm -rf "$DEST"
  mkdir -p "$DEST"
  cp "$SRC/grammar.js" "$DEST/" 2>/dev/null || true
  cp -r "$SRC/src" "$DEST/src"
  [ -f "$SRC/package.json" ] && cp "$SRC/package.json" "$DEST/"
  [ -f "$SRC/tree-sitter.json" ] && cp "$SRC/tree-sitter.json" "$DEST/"
  # shared scanner headers: php/typescript/tsx scanners include
  # ../../common/scanner.h — vendor the package's common/ INTO the grammar
  # dir and rewrite the include depth so each grammar is self-contained
  if grep -q '\.\./\.\./common/' "$DEST/src/scanner.c" 2>/dev/null; then
    PKGROOT="$TMP/x/package"
    if [ -d "$PKGROOT/common" ]; then
      mkdir -p "$DEST/common"
      cp -r "$PKGROOT/common/." "$DEST/common/"
      sed -i 's#\.\./\.\./common/#../common/#g' "$DEST/src/scanner.c"
      echo "  + vendored shared common/ (include rewritten)"
    fi
  fi
  echo "  vendored $(find "$DEST" \( -name '*.c' -o -name '*.js' -o -name '*.json' \) | xargs wc -l 2>/dev/null | tail -1 | awk '{print $1}') lines"
done
echo "=== grammar sources: $(du -sh "$ROOT/grammar-sources" | cut -f1) total ==="
[ -n "$FAIL" ] && echo "SKIPPED:$FAIL (prebuilt wasms remain for these)" || true
